WITH item_sales AS ( SELECT i.i_item_sk, i.i_category, i.i_product_name, SUM(cs.cs_quantity) AS total_qty, SUM(cs.cs_net_profit) AS total_profit, AVG(CASE WHEN cs.cs_ext_list_price = 0 THEN 0 ELSE cs.cs_ext_discount_amt / cs.cs_ext_list_price END) * 100 AS avg_discount_pct, AVG(hd.hd_income_band_sk) AS avg_income_band FROM catalog_sales cs JOIN item i ON cs.cs_item_sk = i.i_item_sk JOIN promotion p ON cs.cs_promo_sk = p.p_promo_sk JOIN household_demographics hd ON cs.cs_bill_hdemo_sk = hd.hd_demo_sk GROUP BY i.i_item_sk, i.i_category, i.i_product_name ) SELECT i_item_sk, i_category, i_product_name, total_qty, total_profit, avg_discount_pct, avg_income_band, profit_per_unit, CASE WHEN profit_per_unit < 5 THEN 'Low' WHEN profit_per_unit BETWEEN 5 AND 10 THEN 'Medium' ELSE 'High' END AS profit_level, RANK() OVER (PARTITION BY i_category ORDER BY profit_per_unit DESC) AS profit_rank FROM ( SELECT i_item_sk, i_category, i_product_name, total_qty, total_profit, avg_discount_pct, avg_income_band, total_profit / NULLIF(total_qty, 0) AS profit_per_unit FROM item_sales ) t ORDER BY i_category, profit_rank
